sys_script.script:
(function executeRule(current, previous) {

    // Add your code here 
    var changeDetails = '';

    if (current.trip_type != previous.trip_type) {
        changeDetails += "\nTRIP TYPE has changed from " + previous.trip_type + " to " + current.trip_type;
    }
    if (current.departing_on != previous.departing_on) {
        changeDetails += "\nDEPARTING ON has changed from " + previous.departing_on + " to " + current.departing_on;
    }
    if (current.returning_on != previous.returning_on) {
        changeDetails += "\nRETURNING ON has changed from " + previous.returning_on + " to " + current.returning_on;
    }
    if (current.leaving_from != previous.leaving_from) {
        changeDetails += "\nLEAVING FROM has changed from " + previous.leaving_from.port + " to " + current.leaving_from.port;
    }
    if (current.going_to != previous.going_to) {
        changeDetails += "\nGOING TO has changed from " + previous.going_to.port + " to " + current.going_to.port;
    }
	if (current.cabin_class != previous.cabin_class) {
        changeDetails += "\nCABIN CLASS has changed from "+ previous.cabin_class.getDisplayValue() + " to " + current.cabin_class.getDisplayValue();
    }
	if (current.business_justification != previous.business_justification) {
        changeDetails += "\nBUSINESS JUSTIFICATION has changed from "+ previous.business_justification + " to " + current.business_justification;
    }

	if (current.state == 12) {
        changeDetails += "\nTravel request has been CANCELLED.";
    }

	changeDetails = "Changes made on the travel request:\n"+ changeDetails;
	current.user_changing_request = changeDetails;
	current.work_notes=changeDetails;

})(current, previous);
